"""Integration tests with independent filesystem tools (mkfs.fat / mtools)."""

import shutil
import subprocess
from pathlib import Path

import pytest

from recoverx.domain.enums import FileSystemType
from recoverx.filesystems.fat.parser import FatFileSystem
from recoverx.infrastructure.storage.image import DiskImageReader

HAS_MKFS_FAT = shutil.which("mkfs.fat") is not None


@pytest.mark.skipif(not HAS_MKFS_FAT, reason="mkfs.fat is not installed on this host")
def test_mkfs_fat_generated_image(tmp_path: Path) -> None:
    """Verify that images generated by official mkfs.fat are detected and parsed correctly."""
    img_path = tmp_path / "mkfs_fat32.img"
    # Create 64 MB empty file
    with open(img_path, "wb") as f:
        f.seek(64 * 1024 * 1024 - 1)
        f.write(b"\x00")

    # Format using mkfs.fat -F 32 -n LINUX_FAT
    res = subprocess.run(
        ["mkfs.fat", "-F", "32", "-n", "LINUX_FAT", str(img_path)],
        capture_output=True,
        text=True,
        check=False,
    )
    assert res.returncode == 0, f"mkfs.fat failed: {res.stderr}"

    fs = FatFileSystem()
    with DiskImageReader(img_path) as reader:
        assert fs.detect(reader)
        info = fs.get_fs_info(reader)
        assert info is not None
        assert info.fs_type == FileSystemType.FAT32
        assert "LINUX_FAT" in info.volume_label
        assert info.cluster_size_bytes in (512, 1024, 2048, 4096)
